class Node:
    def __init__(self, val, next=None, random=None):
        self.val = val
        self.next = next
        self.random = random

def random_list_check(spec, copy):
    original = [Node(v) for v, _ in spec]
    for i, (_, r) in enumerate(spec):
        if i + 1 < len(original):
            original[i].next = original[i + 1]
        if r >= 0:
            original[i].random = original[r]
    originals = {id(n) for n in original}

    head = copy(original[0] if original else None)

    for i, (v, r) in enumerate(spec):
        nxt = original[i + 1] if i + 1 < len(original) else None
        rnd = original[r] if r >= 0 else None
        if original[i].val != v or original[i].next is not nxt or original[i].random is not rnd:
            return 'the original list was modified'

    copies = []
    index = {}
    n = head
    while n is not None:
        if id(n) in originals:
            return f'not a deep copy: node {len(copies)} is an original node'
        if id(n) in index:
            return "the copy's next pointers loop back on themselves"
        if len(copies) == len(original):
            return 'the copy is longer than the original'
        index[id(n)] = len(copies)
        copies.append(n)
        n = n.next

    out = []
    for n in copies:
        if n.random is None:
            out.append([n.val, -1])
        elif id(n.random) in originals:
            return f"node {len(out)}'s random points into the original list"
        elif id(n.random) not in index:
            return f"node {len(out)}'s random points outside the copied list"
        else:
            out.append([n.val, index[id(n.random)]])
    return out

