public class Node
{
    public int Val;
    public Node? Next;
    public Node? Random;
    public Node(int val) { Val = val; }
}
public static class RandomListHarness
{
    public static object Run(int[][] spec, Func<Node?, Node?> copy)
    {
        var original = spec.Select(p => new Node(p[0])).ToArray();
        for (var i = 0; i < original.Length; i++)
        {
            if (i + 1 < original.Length) original[i].Next = original[i + 1];
            if (spec[i][1] >= 0) original[i].Random = original[spec[i][1]];
        }
        var originals = new HashSet<Node>(original);

        var head = copy(original.Length > 0 ? original[0] : null);

        for (var i = 0; i < original.Length; i++)
        {
            var next = i + 1 < original.Length ? original[i + 1] : null;
            var random = spec[i][1] >= 0 ? original[spec[i][1]] : null;
            if (original[i].Val != spec[i][0] || original[i].Next != next || original[i].Random != random)
                return "the original list was modified";
        }

        var copies = new List<Node>();
        var index = new Dictionary<Node, int>();
        for (var n = head; n != null; n = n.Next)
        {
            if (originals.Contains(n)) return $"not a deep copy: node {copies.Count} is an original node";
            if (index.ContainsKey(n)) return "the copy's next pointers loop back on themselves";
            if (copies.Count == original.Length) return "the copy is longer than the original";
            index[n] = copies.Count;
            copies.Add(n);
        }

        var output = new List<int[]>();
        foreach (var n in copies)
        {
            if (n.Random == null) { output.Add(new[] { n.Val, -1 }); continue; }
            if (originals.Contains(n.Random)) return $"node {output.Count}'s random points into the original list";
            if (!index.TryGetValue(n.Random, out var r)) return $"node {output.Count}'s random points outside the copied list";
            output.Add(new[] { n.Val, r });
        }
        return output.ToArray();
    }
}

